using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading.Tasks;
using Xunit;
using Xunit.Sdk;

internal static class Program
{
    private static void Main(string[] args)
    {
        var assembly = Assembly.Load("StyleCop.Analyzers.Test.CSharp15");
        var source = new StringBuilder("""
            // Generated by the test-performance experiment. Original test bodies and xUnit assertions are unchanged.
            using System;
            using System.Collections.Generic;
            using System.Reflection;
            using System.Threading.Tasks;
            using TUnit.Core;
            namespace TestPerformance;

            """);
        var classIndex = 0;
        var methodCount = 0;
        var testCount = 0;
        var manifest = new StringBuilder();
        foreach (var type in assembly.GetExportedTypes().OrderBy(t => t.FullName))
        {
            var methods = type.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)
                .Where(m => m.IsDefined(typeof(FactAttribute), true)).OrderBy(m => m.Name).ToArray();
            if (methods.Length == 0)
            {
                continue;
            }

            if (type.GetConstructor(Type.EmptyTypes) == null)
            {
                throw new InvalidOperationException($"Unsupported constructor: {type.FullName}");
            }

            var typeName = TypeName(type);
            var className = $"Suite{classIndex++}";
            var exclusive = type.IsDefined(typeof(CollectionAttribute), true)
                || type.IsDefined(typeof(BeforeAfterTestAttribute), true);
            source.AppendLine(exclusive ? "[NotInParallel]" : string.Empty);
            source.AppendLine($"public class {className}");
            source.AppendLine("{");
            for (var i = 0; i < methods.Length; i++)
            {
                var method = methods[i];
                var fact = method.GetCustomAttribute<FactAttribute>(true);
                if (fact.Skip != null)
                {
                    throw new InvalidOperationException($"Unexpected skipped test: {typeName}.{method.Name}");
                }

                var parameters = method.GetParameters();
                source.AppendLine($"    private static readonly MethodInfo Method{i} = TestInvoker.Method(typeof({typeName}), \"{method.Name}\", {parameters.Length});");
                if (fact is TheoryAttribute)
                {
                    var cases = method.GetCustomAttributes<DataAttribute>(true).Sum(a => a.GetData(method).Count());
                    testCount += cases;
                    manifest.AppendLine($"{type.FullName}\t{method.Name}\t{cases}");
                    source.AppendLine($"    public static IEnumerable<TestRow> Data{i}() => TestInvoker.Data(Method{i});");
                    source.AppendLine($"    [MethodDataSource(nameof(Data{i}))]");
                }
                else
                {
                    testCount++;
                    manifest.AppendLine($"{type.FullName}\t{method.Name}\t1");
                }

                if (!exclusive && method.IsDefined(typeof(BeforeAfterTestAttribute), true))
                {
                    source.AppendLine("    [NotInParallel]");
                }

                var arguments = method.IsPublic
                    ? string.Join(", ", parameters.Select((p, n) => $"TestInvoker.Argument<{TypeName(p.ParameterType)}>(row.Arguments[{n}])"))
                    : string.Empty;
                var invocation = method.IsPublic
                    ? $"test.{method.Name}({arguments})"
                    : $"TestInvoker.Invoke(Method{i}, test, {(fact is TheoryAttribute ? "row.Arguments" : "Array.Empty<object>()")})";
                if (method.ReturnType == typeof(void) && method.IsPublic)
                {
                    invocation = $"{{ {invocation}; return Task.CompletedTask; }}";
                }
                else if (method.ReturnType != typeof(Task) && method.ReturnType != typeof(void))
                {
                    throw new InvalidOperationException($"Unsupported return type: {typeName}.{method.Name}");
                }

                source.AppendLine("    [Test]");
                source.AppendLine($"    public Task Run{i}_{method.Name}({(fact is TheoryAttribute ? "TestRow row" : string.Empty)})");
                source.AppendLine($"        => TestInvoker.Run<{typeName}>(Method{i}, test => {invocation});");
                methodCount++;
            }

            source.AppendLine("}");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[0]))!);
        File.WriteAllText(args[0], source.ToString());
        File.WriteAllText(args[0] + ".cases.tsv", manifest.ToString());
        Console.WriteLine($"Generated {testCount} test cases across {methodCount} methods in {classIndex} classes.");
    }

    private static string TypeName(Type type)
    {
        if (type.IsArray)
        {
            return TypeName(type.GetElementType()!) + "[]";
        }

        if (type.IsGenericType)
        {
            var name = type.GetGenericTypeDefinition().FullName!;
            return "global::" + name.Substring(0, name.IndexOf('`')).Replace('+', '.')
                + "<" + string.Join(", ", type.GetGenericArguments().Select(TypeName)) + ">";
        }

        return "global::" + type.FullName!.Replace('+', '.');
    }
}
